journals.script:
{
is_shown_when_inactive = { c:SHU ?= this has_variable = ywc_v03_initialized NOT = { has_variable = ywc_t12_started } }
possible = { c:SHU ?= this ywc_v03_has_capacity = yes ywc_t12_entry_ready = yes NOT = { has_variable = ywc_t12_started } }
immediate = { set_variable = { name = ywc_t12_started value = 1 } set_variable = { name = ywc_t12_stage value = 1550 } set_variable = { name = ywc_t12_pending value = 1550 } change_variable = { name = ywc_v03_active_arc_count add = 1 } change_variable = { name = ywc_v03_visible_task_count add = 1 } }
on_monthly_pulse = { effect = {
if = { limit = { OR = { var:ywc_t12_stage ?= 1551 var:ywc_t12_stage ?= 1554 } NOT = { ywc_t12_partner_current = yes } NOT = { has_variable = ywc_t12_outcome } } set_variable = { name = ywc_t12_partner_lost value = 1 } c:DMG ?= { remove_variable = ywc_t12_pending } if = { limit = { var:ywc_t12_stage ?= 1551 } set_variable = { name = ywc_t12_stage value = 1552 } set_variable = { name = ywc_t12_pending value = 1552 } } else_if = { limit = { var:ywc_t12_stage ?= 1554 } set_variable = { name = ywc_t12_stage value = 1555 } set_variable = { name = ywc_t12_pending value = 1555 } } set_variable = { name = ywc_t12_wait_months value = 0 } change_variable = { name = ywc_t12_popup_epoch add = 1 } }
else_if = { limit = { OR = { var:ywc_t12_stage ?= 1551 var:ywc_t12_stage ?= 1554 } ywc_t12_partner_current = yes NOT = { has_variable = ywc_t12_outcome } } if = { limit = { NOT = { has_variable = ywc_t12_wait_months } } set_variable = { name = ywc_t12_wait_months value = 1 } } else = { change_variable = { name = ywc_t12_wait_months add = 1 } } if = { limit = { var:ywc_t12_wait_months >= 6 } set_variable = { name = ywc_t12_outcome value = 4 } set_variable = { name = ywc_t12_stage value = 1557 } remove_variable = ywc_t12_pending set_variable = { name = ywc_t12_wait_months value = 0 } c:DMG ?= { remove_variable = ywc_t12_pending } change_variable = { name = ywc_t12_popup_epoch add = 1 } } }
if = { limit = { var:ywc_t12_stage ?= 1556 has_variable = ywc_t12_shu_verdict NOT = { has_variable = ywc_t12_partner_verdict_note } NOT = { ywc_t12_partner_current = yes } NOT = { has_variable = ywc_t12_outcome } } set_variable = { name = ywc_t12_partner_lost value = 1 } set_variable = { name = ywc_t12_stage value = 1557 } set_variable = { name = ywc_t12_pending value = 1557 } set_variable = { name = ywc_t12_wait_months value = 0 } c:DMG ?= { remove_variable = ywc_t12_pending } change_variable = { name = ywc_t12_popup_epoch add = 1 } }
else_if = { limit = { var:ywc_t12_stage ?= 1556 has_variable = ywc_t12_shu_verdict NOT = { has_variable = ywc_t12_partner_verdict_note } ywc_t12_partner_current = yes NOT = { has_variable = ywc_t12_outcome } } if = { limit = { NOT = { has_variable = ywc_t12_wait_months } } set_variable = { name = ywc_t12_wait_months value = 1 } } else = { change_variable = { name = ywc_t12_wait_months add = 1 } } if = { limit = { var:ywc_t12_wait_months >= 6 } set_variable = { name = ywc_t12_outcome value = 4 } set_variable = { name = ywc_t12_stage value = 1557 } remove_variable = ywc_t12_pending set_variable = { name = ywc_t12_wait_months value = 0 } c:DMG ?= { remove_variable = ywc_t12_pending } change_variable = { name = ywc_t12_popup_epoch add = 1 } } }
if = { limit = { ywc_t12_shu_delivery_1550 = yes } trigger_event = { id = ywc_society.1550 } }
if = { limit = { ywc_t12_shu_delivery_1552 = yes } trigger_event = { id = ywc_society.1552 } }
if = { limit = { ywc_t12_shu_delivery_1553 = yes } trigger_event = { id = ywc_society.1553 } }
if = { limit = { ywc_t12_shu_delivery_1555 = yes } trigger_event = { id = ywc_society.1555 } }
if = { limit = { ywc_t12_shu_delivery_1556 = yes } trigger_event = { id = ywc_society.1556 } }
if = { limit = { ywc_t12_shu_delivery_1557 = yes } trigger_event = { id = ywc_society.1557 } }
} }
on_complete = { ywc_t12_release_capacity = yes }
on_fail = { ywc_t12_release_capacity = yes }
}
